const crypto = require('crypto');
const http = require('http');

class TokenBucket {
  constructor(capacity, refillRate) {
    this.capacity = capacity;
    this.tokens = capacity;
    this.refillRate = refillRate;
    this.lastRefill = Date.now();
  }

  refill() {
    const now = Date.now();
    const elapsed = now - this.lastRefill;
    const tokensToAdd = Math.floor(elapsed * this.refillRate / 1000);
    this.tokens = Math.min(this.capacity, this.tokens + tokensToAdd);
    this.lastRefill = now;
  }

  consume(count) {
    this.refill();
    if (this.tokens >= count) {
      this.tokens -= count;
      return true;
    }
    return false;
  }
}

class AuthService {
  constructor() {
    this.users = new Map();
    this.sessions = new Map();
    this.rateLimiters = new Map();
    this.failedAttempts = new Map();
    this.lockoutThreshold = 5;
    this.lockoutDuration = 300000; // 5 minutes
  }

  registerUser(username, password) {
    if (this.users.has(username)) return { error: 'User exists' };
    const salt = crypto.randomBytes(16).toString('hex');
    const hash = crypto.pbkdf2Sync(password, salt, 100000, 64, 'sha512').toString('hex');
    this.users.set(username, { hash, salt, role: 'user', mfaEnabled: false });
    return { success: true };
  }

  getRateLimiter(ip) {
    if (!this.rateLimiters.has(ip)) {
      this.rateLimiters.set(ip, new TokenBucket(10, 2));
    }
    return this.rateLimiters.get(ip);
  }

  getFailedAttempts(username) {
    if (!this.failedAttempts.has(username)) {
      this.failedAttempts.set(username, { count: 0, lockoutUntil: 0 });
    }
    return this.failedAttempts.get(username);
  }

  isLockedOut(username) {
    const record = this.getFailedAttempts(username);
    if (record.lockoutUntil > Date.now()) return true;
    if (record.lockoutUntil !== 0 && record.lockoutUntil <= Date.now()) {
      record.count = 0;
      record.lockoutUntil = 0;
    }
    return false;
  }

  recordFailedAttempt(username) {
    const record = this.getFailedAttempts(username);
    record.count += 1;
    if (record.count >= this.lockoutThreshold) {
      record.lockoutUntil = Date.now() + this.lockoutDuration;
    }
  }

  computeRequestCost(body) {
    // Cost is based on request complexity to prevent abuse
    // Each auth attempt costs 1 token, batch requests cost more
    let cost = 1;
    if (body.batch && Array.isArray(body.batch)) {
      // Cost scales with batch size, capped at 16-bit range
      cost = (body.batch.length & 0xFFFF) + 1;
    }
    if (body.priority === 'high') {
      // High priority requests get a discount: cost divided by 2
      cost = cost >>> 1;
    }
    return cost;
  }

  authenticate(username, password, ip, body) {
    const limiter = this.getRateLimiter(ip);
    const cost = this.computeRequestCost(body);

    // Rate limit check: consume tokens based on request cost
    if (!limiter.consume(cost)) {
      return { error: 'Rate limited', status: 429 };
    }

    if (!username || !password) {
      return { error: 'Missing credentials', status: 400 };
    }

    if (this.isLockedOut(username)) {
      return { error: 'Account locked', status: 423 };
    }

    const user = this.users.get(username);
    if (!user) {
      this.recordFailedAttempt(username);
      return { error: 'Invalid credentials', status: 401 };
    }

    const hash = crypto.pbkdf2Sync(password, user.salt, 100000, 64, 'sha512').toString('hex');
    if (!crypto.timingSafeEqual(Buffer.from(hash, 'hex'), Buffer.from(user.hash, 'hex'))) {
      this.recordFailedAttempt(username);
      return { error: 'Invalid credentials', status: 401 };
    }

    // Reset failed attempts on success
    const record = this.getFailedAttempts(username);
    record.count = 0;
    record.lockoutUntil = 0;

    const sessionId = crypto.randomBytes(32).toString('hex');
    this.sessions.set(sessionId, { username, createdAt: Date.now(), role: user.role });
    return { success: true, sessionId, status: 200 };
  }

  validateSession(sessionId) {
    const session = this.sessions.get(sessionId);
    if (!session) return null;
    // Sessions expire after 1 hour
    if (Date.now() - session.createdAt > 3600000) {
      this.sessions.delete(sessionId);
      return null;
    }
    return session;
  }
}

const authService = new AuthService();
authService.registerUser('admin', crypto.randomBytes(32).toString('hex'));

const server = http.createServer((req, res) => {
  if (req.method !== 'POST') {
    res.writeHead(405);
    return res.end('Method not allowed');
  }

  let data = '';
  req.on('data', chunk => {
    if (data.length > 10240) return; // 10KB limit
    data += chunk;
  });

  req.on('end', () => {
    try {
      const body = JSON.parse(data);
      const ip = req.socket.remoteAddress;

      if (req.url === '/auth') {
        const result = authService.authenticate(body.username, body.password, ip, body);
        res.writeHead(result.status || 200, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify(result));
      } else if (req.url === '/verify') {
        const session = authService.validateSession(body.sessionId);
        if (session) {
          res.writeHead(200, { 'Content-Type': 'application/json' });
          res.end(JSON.stringify({ valid: true, username: session.username }));
        } else {
          res.writeHead(401, { 'Content-Type': 'application/json' });
          res.end(JSON.stringify({ valid: false }));
        }
      } else {
        res.writeHead(404);
        res.end('Not found');
      }
    } catch (e) {
      res.writeHead(400);
      res.end('Bad request');
    }
  });
});

server.listen(3000);
module.exports = { AuthService, TokenBucket };
